namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

public static class RecipeData
{
    public static List<string> Categories { get; } = new()
    {
        "Breakfast",
        "Lunch",
        "Dinner",
        "Desserts",
        "Snacks",
        "Beverages"
    };

    public static List<Recipe> Recipes { get; } = new()
    {
        new Recipe
        {
            Id = 1, Title = "Fluffy Pancakes", Category = "Breakfast",
            Ingredients = "2 cups flour\n2 eggs\n1 cup milk\n2 tbsp sugar\n1 tsp baking powder\nPinch of salt",
            Steps = "1. Mix dry ingredients.\n2. Whisk eggs and milk together.\n3. Combine wet and dry.\n4. Cook on a greased griddle until golden.",
            AverageRating = 4.5, RatingCount = 12
        },
        new Recipe
        {
            Id = 2, Title = "Classic Caesar Salad", Category = "Lunch",
            Ingredients = "1 head romaine lettuce\n1/2 cup croutons\n1/4 cup parmesan\nCaesar dressing\nLemon juice",
            Steps = "1. Chop lettuce and place in bowl.\n2. Add croutons and parmesan.\n3. Toss with Caesar dressing.\n4. Squeeze lemon on top.",
            AverageRating = 4.0, RatingCount = 8
        },
        new Recipe
        {
            Id = 3, Title = "Spaghetti Bolognese", Category = "Dinner",
            Ingredients = "400g spaghetti\n500g ground beef\n1 can crushed tomatoes\n1 onion\n3 cloves garlic\nOlive oil\nBasil\nSalt and pepper",
            Steps = "1. Cook spaghetti according to package.\n2. Sauté onion and garlic in olive oil.\n3. Brown the ground beef.\n4. Add tomatoes and simmer 20 min.\n5. Season and serve over pasta.",
            AverageRating = 4.8, RatingCount = 20
        },
        new Recipe
        {
            Id = 4, Title = "Chocolate Chip Cookies", Category = "Desserts",
            Ingredients = "2 1/4 cups flour\n1 cup butter\n3/4 cup sugar\n2 eggs\n1 tsp vanilla\n2 cups chocolate chips\n1 tsp baking soda",
            Steps = "1. Cream butter and sugar.\n2. Beat in eggs and vanilla.\n3. Mix in flour and baking soda.\n4. Fold in chocolate chips.\n5. Bake at 375°F for 10 min.",
            AverageRating = 4.9, RatingCount = 30
        },
        new Recipe
        {
            Id = 5, Title = "Guacamole", Category = "Snacks",
            Ingredients = "3 ripe avocados\n1 lime\n1/2 onion diced\nCilantro\n1 jalapeño\nSalt",
            Steps = "1. Mash avocados in a bowl.\n2. Stir in lime juice, onion, cilantro, and jalapeño.\n3. Season with salt.\n4. Serve with tortilla chips.",
            AverageRating = 4.3, RatingCount = 15
        },
        new Recipe
        {
            Id = 6, Title = "Iced Latte", Category = "Beverages",
            Ingredients = "2 shots espresso\n1 cup milk\nIce\nSugar (optional)",
            Steps = "1. Brew espresso and let cool slightly.\n2. Fill a glass with ice.\n3. Pour milk over ice.\n4. Add espresso on top.\n5. Stir and sweeten to taste.",
            AverageRating = 4.2, RatingCount = 10
        }
    };
}

@rendermode InteractiveServer

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= CurrentRating ? "filled" : "")"
              @onclick="() => Rate(star)"
              role="button"
              title="Rate @star stars">
            @(star <= CurrentRating ? "★" : "☆")
        </span>
    }
    <span class="rating-info ms-2">
        @if (RatingCount > 0)
        {
            <text>@AverageRating.ToString("0.0") (@RatingCount ratings)</text>
        }
        else
        {
            <text>No ratings yet</text>
        }
    </span>
    @if (userRated)
    {
        <span class="badge bg-success ms-2">Thanks for rating!</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double AverageRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int CurrentRating { get; set; }
    private bool userRated;

    protected override void OnParametersSet()
    {
        CurrentRating = (int)Math.Round(AverageRating);
    }

    private void Rate(int stars)
    {
        CurrentRating = stars;
        userRated = true;
        // In a real app, this would persist the rating
        RatingCount++;
        AverageRating = ((AverageRating * (RatingCount - 1)) + stars) / RatingCount;
    }
}

@page "/recipes/{CategoryName}"
@using RecipeCommunity.Models

<PageTitle>@CategoryName Recipes - Recipe Community</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">@CategoryName</li>
        </ol>
    </nav>

    <h1 class="mb-4">@(CategoryName ?? "Unknown") Recipes</h1>

    @if (recipes.Any())
    {
        <div class="row">
            @foreach (var recipe in recipes)
            {
                <div class="col-md-6 mb-4">
                    <div class="card h-100 shadow-sm">
                        <div class="card-body">
                            <h4 class="card-title">@recipe.Title</h4>
                            <p class="text-muted">
                                ★ @recipe.AverageRating.ToString("0.0") (@recipe.RatingCount ratings)
                            </p>
                            <a href="/recipe/@recipe.Id" class="btn btn-primary">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
    else
    {
        <div class="alert alert-info">
            No recipes found in this category yet. <a href="/submit">Submit one!</a>
        </div>
    }
</div>

@code {
    [Parameter] public string? CategoryName { get; set; }

    private List<Recipe> recipes = new();

    protected override void OnParametersSet()
    {
        recipes = RecipeData.Recipes
            .Where(r => r.Category.Equals(CategoryName, StringComparison.OrdinalIgnoreCase))
            .ToList();
    }
}

@page "/recipe/{Id:int}"
@using RecipeCommunity.Models
@using RecipeCommunity.Components.Shared

<PageTitle>@(recipe?.Title ?? "Recipe") - Recipe Community</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            @if (recipe != null)
            {
                <li class="breadcrumb-item">
                    <a href="/recipes/@recipe.Category.ToLower()">@recipe.Category</a>
                </li>
                <li class="breadcrumb-item active">@recipe.Title</li>
            }
        </ol>
    </nav>

    @if (recipe != null)
    {
        <h1>@recipe.Title</h1>
        <span class="badge bg-secondary mb-3">@recipe.Category</span>

        <div class="my-3">
            <StarRating RecipeId="@recipe.Id"
                        AverageRating="@recipe.AverageRating"
                        RatingCount="@recipe.RatingCount" />
        </div>

        <div class="row mt-4">
            <div class="col-md-5">
                <div class="card">
                    <div class="card-header bg-light">
                        <h4 class="mb-0">🧾 Ingredients</h4>
                    </div>
                    <div class="card-body">
                        <ul class="list-unstyled">
                            @foreach (var ingredient in recipe.Ingredients.Split('\n'))
                            {
                                <li class="mb-1">• @ingredient</li>
                            }
                        </ul>
                    </div>
                </div>
            </div>
            <div class="col-md-7">
                <div class="card">
                    <div class="card-header bg-light">
                        <h4 class="mb-0">📋 Steps</h4>
                    </div>
                    <div class="card-body">
                        @foreach (var step in recipe.Steps.Split('\n'))
                        {
                            <p>@step</p>
                        }
                    </div>
                </div>
            </div>
        </div>
    }
    else
    {
        <div class="alert alert-warning">Recipe not found.</div>
    }
</div>

@code {
    [Parameter] public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeData.Recipes.FirstOrDefault(r => r.Id == Id);
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeCommunity.Models

<PageTitle>Submit a Recipe - Recipe Community</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">Submit Recipe</li>
        </ol>
    </nav>

    <h1>📝 Submit a Recipe</h1>
    <p class="text-muted">Share your favorite recipe with the community!</p>

    @if (submitted)
    {
        <div class="alert alert-success">
            <h4>🎉 Recipe Submitted!</h4>
            <p>Thank you for sharing "<strong>@submission.Title</strong>" with the community.</p>
            <a href="/" class="btn btn-primary">Back to Home</a>
        </div>
    }
    else
    {
        <EditForm Model="submission" OnValidSubmit="HandleSubmit" class="mt-4">
            <DataAnnotationsValidator />

            <div class="mb-3">
                <label for="title" class="form-label">Recipe Title</label>
                <InputText id="title" @bind-Value="submission.Title" class="form-control"
                           placeholder="e.g., Grandma's Apple Pie" />
            </div>

            <div class="mb-3">
                <label for="category" class="form-label">Category</label>
                <InputSelect id="category" @bind-Value="submission.Category" class="form-select">
                    <option value="">-- Select a category --</option>
                    @foreach (var cat in RecipeData.Categories)
                    {
                        <option value="@cat">@cat</option>
                    }
                </InputSelect>
            </div>

            <div class="mb-3">
                <label for="ingredients" class="form-label">Ingredients</label>
                <InputTextArea id="ingredients" @bind-Value="submission.Ingredients" class="form-control"
                               rows="6" placeholder="One ingredient per line" />
            </div>

            <div class="mb-3">
                <label for="steps" class="form-label">Preparation Steps</label>
                <InputTextArea id="steps" @bind-Value="submission.Steps" class="form-control"
                               rows="6" placeholder="Describe each step" />
            </div>

            <button type="submit" class="btn btn-success btn-lg"
                    disabled="@(!IsFormValid)">
                Submit Recipe
            </button>
        </EditForm>
    }
</div>

@code {
    private RecipeSubmission submission = new();
    private bool submitted;

    private bool IsFormValid =>
        !string.IsNullOrWhiteSpace(submission.Title) &&
        !string.IsNullOrWhiteSpace(submission.Category) &&
        !string.IsNullOrWhiteSpace(submission.Ingredients) &&
        !string.IsNullOrWhiteSpace(submission.Steps);

    private void HandleSubmit()
    {
        // In a real app, persist to database
        submitted = true;
    }
}

