@using RecipeCommunity.Models
@using RecipeCommunity.Components.Shared

<PageTitle>@(recipe?.Title ?? "Recipe") - Recipe Community</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            @if (recipe != null)
            {
                <li class="breadcrumb-item">
                    <a href="/recipes/@recipe.Category.ToLower()">@recipe.Category</a>
                </li>
                <li class="breadcrumb-item active">@recipe.Title</li>
            }
        </ol>
    </nav>

    @if (recipe != null)
    {
        <h1>@recipe.Title</h1>
        <span class="badge bg-secondary mb-3">@recipe.Category</span>

        <div class="my-3">
            <StarRating RecipeId="@recipe.Id"
                        AverageRating="@recipe.AverageRating"
                        RatingCount="@recipe.RatingCount" />
        </div>

        <div class="row mt-4">
            <div class="col-md-5">
                <div class="card">
                    <div class="card-header bg-light">
                        <h4 class="mb-0">🧾 Ingredients</h4>
                    </div>
                    <div class="card-body">
                        <ul class="list-unstyled">
                            @foreach (var ingredient in recipe.Ingredients.Split('\n'))
                            {
                                <li class="mb-1">• @ingredient</li>
                            }
                        </ul>
                    </div>
                </div>
            </div>
            <div class="col-md-7">
                <div class="card">
                    <div class="card-header bg-light">
                        <h4 class="mb-0">📋 Steps</h4>
                    </div>
                    <div class="card-body">
                        @foreach (var step in recipe.Steps.Split('\n'))
                        {
                            <p>@step</p>
                        }
                    </div>
                </div>
            </div>
        </div>
    }
    else
    {
        <div class="alert alert-warning">Recipe not found.</div>
    }
</div>

@code {
    [Parameter] public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeData.Recipes.FirstOrDefault(r => r.Id == Id);
    }
}
"}

