toolArgs.file_text:
@page "/recipes/{CategoryName}"
@using RecipeCommunity.Models

<PageTitle>@CategoryName Recipes - Recipe Community</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">@CategoryName</li>
        </ol>
    </nav>

    <h1 class="mb-4">@(CategoryName ?? "Unknown") Recipes</h1>

    @if (recipes.Any())
    {
        <div class="row">
            @foreach (var recipe in recipes)
            {
                <div class="col-md-6 mb-4">
                    <div class="card h-100 shadow-sm">
                        <div class="card-body">
                            <h4 class="card-title">@recipe.Title</h4>
                            <p class="text-muted">
                                ★ @recipe.AverageRating.ToString("0.0") (@recipe.RatingCount ratings)
                            </p>
                            <a href="/recipe/@recipe.Id" class="btn btn-primary">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
    else
    {
        <div class="alert alert-info">
            No recipes found in this category yet. <a href="/submit">Submit one!</a>
        </div>
    }
</div>

@code {
    [Parameter] public string? CategoryName { get; set; }

    private List<Recipe> recipes = new();

    protected override void OnParametersSet()
    {
        recipes = RecipeData.Recipes
            .Where(r => r.Category.Equals(CategoryName, StringComparison.OrdinalIgnoreCase))
            .ToList();
    }
}

@page "/recipe/{Id:int}"
@using RecipeCommunity.Models
@using RecipeCommunity.Components.Shared

<PageTitle>@(recipe?.Title ?? "Recipe") - Recipe Community</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            @if (recipe != null)
            {
                <li class="breadcrumb-item">
                    <a href="/recipes/@recipe.Category.ToLower()">@recipe.Category</a>
                </li>
                <li class="breadcrumb-item active">@recipe.Title</li>
            }
        </ol>
    </nav>

    @if (recipe != null)
    {
        <h1>@recipe.Title</h1>
        <span class="badge bg-secondary mb-3">@recipe.Category</span>

        <div class="my-3">
            <StarRating RecipeId="@recipe.Id"
                        AverageRating="@recipe.AverageRating"
                        RatingCount="@recipe.RatingCount" />
        </div>

        <div class="row mt-4">
            <div class="col-md-5">
                <div class="card">
                    <div class="card-header bg-light">
                        <h4 class="mb-0">🧾 Ingredients</h4>
                    </div>
                    <div class="card-body">
                        <ul class="list-unstyled">
                            @foreach (var ingredient in recipe.Ingredients.Split('\n'))
                            {
                                <li class="mb-1">• @ingredient</li>
                            }
                        </ul>
                    </div>
                </div>
            </div>
            <div class="col-md-7">
                <div class="card">
                    <div class="card-header bg-light">
                        <h4 class="mb-0">📋 Steps</h4>
                    </div>
                    <div class="card-body">
                        @foreach (var step in recipe.Steps.Split('\n'))
                        {
                            <p>@step</p>
                        }
                    </div>
                </div>
            </div>
        </div>
    }
    else
    {
        <div class="alert alert-warning">Recipe not found.</div>
    }
</div>

@code {
    [Parameter] public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeData.Recipes.FirstOrDefault(r => r.Id == Id);
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeCommunity.Models

<PageTitle>Submit a Recipe - Recipe Community</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">Submit Recipe</li>
        </ol>
    </nav>

    <h1>📝 Submit a Recipe</h1>
    <p class="text-muted">Share your favorite recipe with the community!</p>

    @if (submitted)
    {
        <div class="alert alert-success">
            <h4>🎉 Recipe Submitted!</h4>
            <p>Thank you for sharing "<strong>@submission.Title</strong>" with the community.</p>
            <a href="/" class="btn btn-primary">Back to Home</a>
        </div>
    }
    else
    {
        <EditForm Model="submission" OnValidSubmit="HandleSubmit" class="mt-4">
            <DataAnnotationsValidator />

            <div class="mb-3">
                <label for="title" class="form-label">Recipe Title</label>
                <InputText id="title" @bind-Value="submission.Title" class="form-control"
                           placeholder="e.g., Grandma's Apple Pie" />
            </div>

            <div class="mb-3">
                <label for="category" class="form-label">Category</label>
                <InputSelect id="category" @bind-Value="submission.Category" class="form-select">
                    <option value="">-- Select a category --</option>
                    @foreach (var cat in RecipeData.Categories)
                    {
                        <option value="@cat">@cat</option>
                    }
                </InputSelect>
            </div>

            <div class="mb-3">
                <label for="ingredients" class="form-label">Ingredients</label>
                <InputTextArea id="ingredients" @bind-Value="submission.Ingredients" class="form-control"
                               rows="6" placeholder="One ingredient per line" />
            </div>

            <div class="mb-3">
                <label for="steps" class="form-label">Preparation Steps</label>
                <InputTextArea id="steps" @bind-Value="submission.Steps" class="form-control"
                               rows="6" placeholder="Describe each step" />
            </div>

            <button type="submit" class="btn btn-success btn-lg"
                    disabled="@(!IsFormValid)">
                Submit Recipe
            </button>
        </EditForm>
    }
</div>

@code {
    private RecipeSubmission submission = new();
    private bool submitted;

    private bool IsFormValid =>
        !string.IsNullOrWhiteSpace(submission.Title) &&
        !string.IsNullOrWhiteSpace(submission.Category) &&
        !string.IsNullOrWhiteSpace(submission.Ingredients) &&
        !string.IsNullOrWhiteSpace(submission.Steps);

    private void HandleSubmit()
    {
        // In a real app, persist to database
        submitted = true;
    }
}

